import{_ as s,o as t,c as a,a2 as i}from"./chunks/framework.doxMM-x8.js";const k=JSON.parse('{"title":"From a Synthetic Publisher to two Lab Viewers","description":"","frontmatter":{"docLocale":"en","counterpart":"/tutorials/synthetic-motion","contentType":"tutorial","prev":false,"next":false},"headers":[],"relativePath":"en/tutorials/synthetic-motion.md","filePath":"en/tutorials/synthetic-motion.md"}'),n={name:"en/tutorials/synthetic-motion.md"};function o(r,e,h,l,p,c){return t(),a("div",null,[...e[0]||(e[0]=[i(`<h1 id="from-a-synthetic-publisher-to-two-lab-viewers" tabindex="-1">From a Synthetic Publisher to two Lab Viewers <a class="header-anchor" href="#from-a-synthetic-publisher-to-two-lab-viewers" aria-label="Permalink to &quot;From a Synthetic Publisher to two Lab Viewers&quot;">​</a></h1><p>Goal: use one Python Synthetic Publisher to move real GLB objects in two browsers. Each Viewer keeps its own camera and Inspector selection.</p><p>Complete <a href="./persistent-world">Persistent Labs and objects</a> and <a href="./persistent-assets">Persistent digital assets</a> first. Use the repository Node and pnpm versions, Python 3.10+ with venv and pip, and a desktop browser. Run commands from the repository root. Use Linux or WSL Ubuntu for these Bash and browser verification commands. This local loopback fixture needs no GPU, Newton, or Docker.</p><h2 id="start-isolated-test-data" tabindex="-1">Start isolated test data <a class="header-anchor" href="#start-isolated-test-data" aria-label="Permalink to &quot;Start isolated test data&quot;">​</a></h2><p>Stop previous development services. Start a test instance:</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">pnpm</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> install</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --frozen-lockfile</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">LAB_WORD_MOTION_FIXTURE</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">=</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">true</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> LAB_WORD_DATA_DIR</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">=</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">.scratch/motion-tutorial-data</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;"> pnpm</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> dev</span></span></code></pre></div><p>Open <a href="http://127.0.0.1:5173/lab" target="_blank" rel="noreferrer">http://127.0.0.1:5173/lab</a>. Register a test user and create a Lab named <code>Synthetic motion</code>. Import <code>tests/fixtures/lab/cube.glb</code> in the asset library. Fill in its name, source, license, and version. Use this asset for one object in the Lab. This adds it to the current Lab asset list.</p><ol><li>Open <strong>Synthetic motion</strong>.</li><li>Select the imported GLB and keep <code>30 Hz</code>.</li><li>Click <strong>Prepare and join test session</strong>.</li><li>Close the dialog and observe 20 new model objects.</li></ol><p>The status first waits for a Publisher. Initial preparation registers 20 Entities and Scene Nodes with their initial Placement. Motion frames do not change these records or Registered Location.</p><p>Open the same Lab in a second browser tab with the same logged-in user. Click <strong>Synthetic motion → Join existing session</strong>. The second Viewer can select <code>15 Hz</code>. Closing the dialog keeps the motion connection open.</p><h2 id="start-the-python-publisher" tabindex="-1">Start the Python Publisher <a class="header-anchor" href="#start-the-python-publisher" aria-label="Permalink to &quot;Start the Python Publisher&quot;">​</a></h2><p>Create a key with <code>lab:full</code> on the <strong>API keys</strong> page. The key must belong to the user who created the fixture. Other members can watch but cannot request its Publisher ticket.</p><p>Create an isolated Python environment:</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">python3</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -m</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> venv</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> .scratch/motion-python</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">.scratch/motion-python/bin/python</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -m</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> pip</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> install</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -r</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> tools/synthetic-motion/requirements.txt</span></span></code></pre></div><p>Enter the key at the hidden Bash prompt:</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">read</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -rsp</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> &#39;Lab API key: &#39;</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> MOTION_API_KEY</span></span>
<span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">export</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> MOTION_API_KEY</span></span></code></pre></div><p>Find the Lab identity. This command prints only Lab names and UUIDs:</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">.scratch/motion-python/bin/python</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> -</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;"> &lt;&lt;</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&#39;PY&#39;</span></span>
<span class="line"><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">import json, os, urllib.request</span></span>
<span class="line"><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">request = urllib.request.Request(&#39;http://127.0.0.1:3000/api/v1/lab/labs&#39;,</span></span>
<span class="line"><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">    headers={&#39;Authorization&#39;: &#39;Bearer &#39; + os.environ[&#39;MOTION_API_KEY&#39;]})</span></span>
<span class="line"><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">with urllib.request.urlopen(request, timeout=10) as response:</span></span>
<span class="line"><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">    for lab in json.load(response)[&#39;data&#39;]:</span></span>
<span class="line"><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">        print(lab[&#39;name&#39;], lab[&#39;id&#39;])</span></span>
<span class="line"><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">PY</span></span></code></pre></div><p>Replace <code>&lt;lab-uuid&gt;</code> with the test Lab UUID. Run:</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">.scratch/motion-python/bin/python</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> docs/examples/motion-launch.py</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --lab-id</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;"> &lt;</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">lab-uui</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">d</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">&gt;</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --duration</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> 600</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">unset</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> MOTION_API_KEY</span></span></code></pre></div><p>The <a href="https://github.com/CaiZongyuan/labworld/blob/c80e63c8c063e44ca80c85970b518c35fb448c8e/docs/examples/motion-launch.py" target="_blank" rel="noreferrer">launch example</a> reads fixture metadata and requests a one-use Publisher ticket through authenticated HTTP. It passes the ticket to the <a href="https://github.com/CaiZongyuan/labworld/blob/c80e63c8c063e44ca80c85970b518c35fb448c8e/tools/synthetic-motion/publisher.py" target="_blank" rel="noreferrer">Publisher</a> on stdin. The ticket does not appear in command arguments. The Publisher and Viewers use the same Node listener port.</p><p>Both browsers should show 20 GLB objects moving along smooth paths. Rotate each camera, select an object, and open its Inspector. Camera and selection changes in one tab do not affect the other. Leave the second Viewer during the run, then click <strong>Join existing session</strong>. It receives the current full Snapshot immediately.</p><h2 id="check-the-trajectory-and-boundaries" tabindex="-1">Check the trajectory and boundaries <a class="header-anchor" href="#check-the-trajectory-and-boundaries" aria-label="Permalink to &quot;Check the trajectory and boundaries&quot;">​</a></h2><p>The Synthetic Publisher samples at 30 Hz. It sends 20 body poses and 6 joint values. Each full binary Snapshot contains 632 bytes. The Viewer maps its receive monotonic clock to simulation rate <code>1</code>. It interpolates inside a bounded buffer. Display frame rate and network message rate are separate measurements.</p><p>Let <code>t = sim_time_ns / 1e9</code> and <code>phase = i × 0.2</code>. Body index <code>i</code> runs from 0 to 19:</p><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>x = (i % 5 - 2) × 1.6 + 0.45 × sin(t + phase)</span></span>
<span class="line"><span>y = 0.65 + 0.15 × sin(2 × t + phase)</span></span>
<span class="line"><span>z = (floor(i / 5) - 1.5) × 1.4 + 0.35 × cos(t + phase)</span></span>
<span class="line"><span>yaw = 0.4 × t + i × 0.1</span></span>
<span class="line"><span>joint[j] = 0.5 × sin(t + j × 0.2), j = 0..5</span></span></code></pre></div><p>The wire uses right-handed coordinates, Y up, metres, and XYZW quaternions. Each pose updates the Scene Node root in world space. The centered GLB child offset and static scale <code>0.35</code> remain. The <a href="https://github.com/CaiZongyuan/labworld/blob/c80e63c8c063e44ca80c85970b518c35fb448c8e/packages/contracts/src/motion/index.ts" target="_blank" rel="noreferrer">protocol</a>, <a href="https://github.com/CaiZongyuan/labworld/blob/c80e63c8c063e44ca80c85970b518c35fb448c8e/tools/synthetic-motion/motion_codec.py" target="_blank" rel="noreferrer">Python codec</a>, and <a href="https://github.com/CaiZongyuan/labworld/blob/c80e63c8c063e44ca80c85970b518c35fb448c8e/tools/synthetic-motion/synthetic.py" target="_blank" rel="noreferrer">synthetic trajectory</a> define public contracts.</p><p>The Gateway keeps the current frame in memory. Each Viewer has one pending latest slot. Actual WS <code>bufferedAmount</code> has a 64 KiB soft budget and 256 KiB hard budget. A Viewer blocked for two seconds disconnects. The soft budget reduces its rate to 15 Hz. Fast Viewers do not wait for slow Viewers.</p><p>The fixture requires <code>LAB_WORD_MOTION_FIXTURE=true</code> and a loopback server bind. HTTP and WS check the actual connection source and reject proxy forwarding headers. Viewer admission uses a one-use ticket valid for 30 seconds. Scene mapping starts after admission. A separate ticket and fixed route determine Publisher authority.</p><p>HTTP DTOs are generated from the <a href="https://github.com/CaiZongyuan/labworld/blob/c80e63c8c063e44ca80c85970b518c35fb448c8e/packages/server/src/lab/motion/routes.ts" target="_blank" rel="noreferrer">Node routes</a> through OpenAPI. High-frequency poses do not write the database, <code>world_clock</code>, or SSE. Existing HTTP and business SSE keep their responsibilities. Fixture bindings end when the server stops. Registered objects, assets, and initial layouts remain in the test directory.</p><h2 id="verify-the-source" tabindex="-1">Verify the source <a class="header-anchor" href="#verify-the-source" aria-label="Permalink to &quot;Verify the source&quot;">​</a></h2><p>Install Chromium once. Run the short check and full acceptance separately:</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">pnpm</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> exec</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> playwright</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> install</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> chromium</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">pnpm</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> test:e2e</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> tests/e2e/lab-synthetic-motion.spec.ts</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --grep</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> &#39;motion smoke:&#39;</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">pnpm</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> test:e2e</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> tests/e2e/lab-synthetic-motion.spec.ts</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --grep</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> &#39;motion full:&#39;</span></span></code></pre></div><p>Both commands use <code>.scratch/motion-python/bin/python</code> from the setup above. Set <code>MOTION_E2E_PYTHON=/absolute/path/python</code> to use another isolated environment. The runner checks installed websockets against the exact version in tracked requirements.</p><p>The <a href="https://github.com/CaiZongyuan/labworld/blob/c80e63c8c063e44ca80c85970b518c35fb448c8e/scripts/e2e-server.mjs" target="_blank" rel="noreferrer">motion profile</a> builds the same-origin application and enables the fixture only in its owned backend. It creates isolated data, listener ports, and an observer directory. The backend preload records actual Gateway/WS counters. It does not replace values or block the target. Browser, Publisher, and slow TCP reader owners record and clean their resources. Evidence stays in this run&#39;s directory under <code>.scratch/vnext-m1/</code>.</p><p>The short check covers real Python, two GLB Viewers, admission refusal, raw wire, Object3D trajectories, visible pixels, and socket release. Default <code>pnpm test:e2e</code> and <code>web-journeys</code> CI select this short motion check. They retain all other profiles.</p><p><code>motion full:</code> also covers at least 600 seconds after both Viewers are ready, real slow TCP, stale freeze, independent cameras and selection. It verifies late joins, repeated switches, and resource convergence. This separate full acceptance is mandatory for delivery. The default suite&#39;s short check does not cover its long-run assertions. Record the command, source commit, environment, samples, and cleanup receipts.</p><h2 id="fail-once-and-recover" tabindex="-1">Fail once and recover <a class="header-anchor" href="#fail-once-and-recover" aria-label="Permalink to &quot;Fail once and recover&quot;">​</a></h2><ol><li>Press Ctrl+C in the Publisher terminal.</li><li>Observe interrupted or stale status and frozen last trusted poses in both Viewers.</li><li>Repeat the hidden key prompt and launch command to request a new Publisher ticket and server epoch.</li><li>Observe a new mapping handshake, then resumed current Snapshots in both Viewers.</li></ol><p>After a Viewer error, click <strong>Leave motion</strong>, then <strong>Join existing session</strong>. Reused tickets, old epochs, repeated sequences, or wrong mappings fail explicitly. The Viewer does not interpolate across epochs, time rollback, or long gaps.</p><p>To finish, click <strong>Leave motion</strong> in both Viewers. Stop the Publisher, then stop <code>pnpm dev</code>. The development supervisor stops its Node and Web processes. The test directory contains this tutorial&#39;s persistent assets and objects. Keep it if you need those records.</p><p>Synthetic generates deterministic mathematical trajectories. It does not compute physical contact or create production Simulation Sessions or Lab Recordings. Newton, remote deployment, and reliable recording remain later work.</p><p>TS/Python golden checks require system Python 3. Set <code>PYTHON</code> to override the executable. Normal Node/Web startup and builds remain Python-independent.</p><hr><p>Source version：<code>c80e63c8c063</code> · <a href="https://github.com/CaiZongyuan/labworld/blob/c80e63c8c063e44ca80c85970b518c35fb448c8e/docs/tutorials/synthetic-motion.en.md" target="_blank" rel="noreferrer">Page Markdown</a></p>`,45)])])}const u=s(n,[["render",o]]);export{k as __pageData,u as default};
